g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "portfolio-checks-table",
  "x": 64, "y": 262, "width": 1152, "height": 300,
  "strict_grid": true,
  "column_widths": [336, 816],
  "row_heights": [40, 90, 90, 80],
  "style": {
    "font_family": "Calibri",
    "font_size": 18,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 12, "right": 12, "top": 4, "bottom": 4},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Earlier finding", "bold": true, "align": "l"},
    {"text": "What it means for retaining the extra $75m", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "PE is 21.9%, above the 16% target", "bold": true, "color": "#003657"},
      {"text": "Treat capacity for additional PE exposure as scarce. Compare the incremental TPG opportunity with other investments and with manager and asset-class concentration. A cut frees future capacity; it does not immediately reduce current PE NAV by $75m."}
    ],
    [
      {"text": "OPERF expects to meet TPG's calls", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "Funding is feasible on the case's expected-call statement. Separately stress pension payments and all-manager calls against weak distributions and falling liquid assets. Ability to pay does not make the investment attractive.", "fill": "#F1ECE2"}
    ],
    [
      {"text": "The inception model gives +$2.82m marginal value", "bold": true, "color": "#003657"},
      {"text": "Validate actual future cash-flow differences under the cancellation terms and use a defensible opportunity-cost benchmark. Preserve the $79.9m already contributed and count only agreed compensation terms."}
    ]
  ]
}
